CREATE TABLE "worker_words" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "worker" text NOT NULL,
  "text" text NOT NULL,
  "added_at" bigint NOT NULL,
  "delivered_at" bigint,
  rowid bigint GENERATED ALWAYS AS ("id") STORED,
  PRIMARY KEY ("id")
);

CREATE INDEX "worker_words_pending" ON "worker_words" (worker, id);
